# Streaming Applications Example

Streaming applications is a feature of the E2B Desktop Sandbox.

| Streaming Chrome Window                                 | Streaming VS Code Window                                 |
| ------------------------------------------------------- | -------------------------------------------------------- |
| ![Chrome streaming window](../readme-assets/chrome.png) | ![VS Code streaming window](../readme-assets/vscode.png) |

> [!WARNING]
>
> - Will raise an error if the desired application is not open yet
> - The stream will close once the application closes
> - Creating multiple streams at the same time is not supported, you may have to stop the current stream and start a new one for each application

## How to run

### 1. Get E2B API key

Sign up at [E2B](https://e2b.dev) and get your API key.
Set environment variable `E2B_API_KEY` with your API key.

### 2. Install SDK

```bash
npm install @e2b/desktop
```

### 3. Create Desktop Sandbox

```javascript
import { Sandbox } from '@e2b/desktop'

// Start a new desktop sandbox
const desktop = await Sandbox.create()
console.log('Desktop sandbox created', desktop.sandboxId)

// Launch an application
console.log('Launching Google Chrome')
await desktop.launch('google-chrome') // or vscode, firefox, etc.

// Wait 15s for the application to open
await desktop.wait(15000)

// Stream the application's window
// Note: there can be only one stream at a time
// You need to stop the current stream before streaming another application
console.log('Starting to stream Google Chrome')
await desktop.stream.start({
  windowId: await desktop.getCurrentWindowId(), // if not provided the whole desktop will be streamed
  requireAuth: true,
})

// Get the stream auth key
const authKey = desktop.stream.getAuthKey()

// Print the stream URL
console.log('Stream URL:', desktop.stream.getUrl({ authKey }))

// Do some actions in the application
console.log('Writing to Google Chrome')
await desktop.write('What is the capital of Germany?')

console.log('Pressing Enter')
await desktop.press('Enter')

// wait 15s for page to load
console.log('Waiting 15s')
await desktop.wait(15000)

// Stop the stream
console.log('Stopping the stream')
await desktop.stream.stop()

// Open another application
console.log('Launching VS Code')
await desktop.launch('code')

// Wait 15s for the application to open
await desktop.wait(15000)

// Start streaming the new application
console.log('Starting to stream VS Code')
await desktop.stream.start({
  windowId: await desktop.getCurrentWindowId(), // if not provided the whole desktop will be streamed
  requireAuth: true,
})

// Get the stream auth key
const authKey2 = desktop.stream.getAuthKey()

// Print the stream URL
console.log('Stream URL:', desktop.stream.getUrl({ authKey: authKey2 }))

// Kill the sandbox after the tasks are finished
// await desktop.kill()
```

import 'dotenv/config'
import { app, BrowserWindow } from 'electron'
import { Sandbox } from '@e2b/desktop'

// Additional px to take into the account the window border at the top
const windowFrameHeight = 29

app.on('window-all-closed', () => {
  app.quit()
})

function wait(ms) {
  return new Promise(resolve => setTimeout(resolve, ms))
}

/**
 * @param {string} streamUrl - The URL of the stream to load
 * @param {number} width - The width of the window
 * @param {number} height - The height of the window
 */
async function createWindow(streamUrl, width, height) {
  const win = new BrowserWindow({
    title: 'E2B Desktop',
    width,
    height: height + windowFrameHeight,
    webPreferences: {
      nodeIntegration: false,
      contextIsolation: true,
      webviewTag: true,
    },
  })

  console.log('> Loading stream URL...')
  await win.loadURL(streamUrl)
  console.log(' - Stream URL loaded')
}

/**
 * @param {import('@e2b/desktop').Sandbox} desktop - E2B desktop sandbox
 * @param {number} width - The width of the window
 * @param {number} height - The height of the window
 */
async function moveAround(desktop, width, height) {
  console.log('\n> Randomly moving mouse and right clicking 5 times...')
  for (let i = 0; i < 5; i++) {
    const x = Math.floor(Math.random() * width)
    const y = Math.floor(Math.random() * height)
    await desktop.moveMouse(x, y)
    console.log(` - Moved mouse to ${x}, ${y}`)
    await desktop.rightClick()
    console.log(` - Right clicked ${i}`)
    console.log(' - Waiting 2 seconds...\n')
    await wait(2000)
  }
}

async function main() {
  console.log('> Waiting for electron app to be ready...')
  await app.whenReady()
  console.log(' - Electron app is ready')

  console.log('\n> Starting desktop sandbox...')
  const desktop = await Sandbox.create()
  console.log(' - Desktop sandbox started, ID:', desktop.sandboxId)

  const size = await desktop.getScreenSize()
  console.log(' - Desktop sandbox screen size:', size)

  console.log('\n> Starting desktop stream...')
  await desktop.stream.start({
    requireAuth: true
  })

  console.log('\n> Waiting 5 seconds for the stream to load...')
  for (let i = 5; i > 0; i--) {
    console.log(` - ${i} seconds remaining until the next step...`)
    await wait(1000)
  }

  const authKey = await desktop.stream.getAuthKey()
  const url = desktop.stream.getUrl({ authKey })
  console.log(' - Stream URL:', url)

  console.log('\n> Creating browser window...')
  createWindow(url, size.width, size.height)
  console.log(' - Browser window created')

  await moveAround(desktop, size.width, size.height)

  console.log('\nPress enter to kill the sandbox and close the window...')
  process.stdin.once('data', async () => {
    console.log('\n> Stopping desktop stream...')
    await desktop.stream.stop()
    console.log(' - Desktop stream stopped')

    console.log('\n> Closing browser window...')
    console.log(' - Browser window closed')

    console.log('\n> Killing desktop sandbox...')
    await desktop.kill()
    console.log(' - Desktop sandbox killed')

    app.quit()
  })
}

main().then().catch(console.error)

